    [3310001] = {
        id = 3310001,
        text = "1.追猎计划在社团等级4级时开启，加入社团时间超过48小时且社团基础贡献度到达200的成员可参与此活动",
        minipack = 0,
    },
    [3310003] = {
        id = 3310003,
        text = "3.备战阶段中，社团成员单人挑战社团Boss的3个弱点副本，每天有2次挑战次数，次日凌晨6点重置（3个副本共享次数）",
        minipack = 0,
    },
    [3310005] = {
        id = 3310005,
        text = "5.挑战阶段中，社团成员共同组队挑战社团Boss。社团Boss共有40等级（一个等级即为一轮），每成功击败一级Boss，会继续刷出下一级。下一周期初始挑战Boss等级由上一周期成功挑战最高Boss等级决定（向下调整5级）",
        minipack = 0,
    },
    [471106] = {
        id = 471106,
        text = "#的信仰值消耗-2",
        minipack = 0,
    },
    [3310009] = {
        id = 3310009,
        text = "9.作战奖励分为Boss首通奖励和击杀奖励。首次击杀Boss可以拿到首通奖励，在下一周期备战阶段开启前均可领取，未领取的首通奖励不会补发；本周期结束后会对社团挑战Boss等级进行结算，社团成员可以获得最高等级Boss及向下2级内的Boss击杀奖励，在下一周期挑战阶段开启前均可领取，未领取的击杀奖励不会补发",
        minipack = 0,
    },
    [3310011] = {
        id = 3310011,
        text = "11.社团荣誉与社团竞赛排名关联，为一些活动限定奖励，作为后期规划内容，敬请期待",
        minipack = 0,
    },
    [3310013] = {
        id = 3310013,
        text = "13.伤害占比奖励结算要统计最终的个人伤害和社团成员造成的总伤害，所以领取奖励时间会稍微晚一些，从下周一早上8点开始，在下一周期挑战阶段开启前均可领取，未领取的个人伤害占比奖励不会补发",
        minipack = 0,
    },
