        text = "生死狙击",
        minipack = 0,
    },
    [13316043] = {
        id = 13316043,
        text = "还在读国中的少女，冷静的头脑足以让她成为侦探得力的助手。",
        minipack = 0,
    },
    [910108] = {
        id = 910108,
        text = "普通的真谛",
        minipack = 0,
    },
    [13316059] = {
