    [2200108] = {
        id = 2200108,
        text = "破空剑舞",
        minipack = 0,
    },
    [2200110] = {
        id = 2200110,
        text = "挥舞鏖杀公攻击近战范围内的敌人，可连续释放三段攻击。\n一段：造成1次攻击力60%的物理伤害；\n二段：造成1次攻击力70%的物理伤害；\n三段：造成1次攻击力70%的物理伤害。",
        minipack = 0,
    },
    [13322107] = {
        id = 13322107,
        text = "北欧神话中，潜伏在“世界树”根部，不断啃食世界树的邪恶黑龙，具有颠覆中庭和阿斯加德的邪恶力量，被称为至暗的黑龙之王。天空舰“尼德霍格”拥有和黑龙王同样的破坏之力，得到世人的敬畏",
        minipack = 0,
    },
    [2200120] = {
        id = 2200120,
        text = "使用鏖杀公挥舞出剑气攻击前方敌人。\n对敌人造成3次共计攻击力180%的物理伤害。",
        minipack = 0,
    },
    [30502] = {
        id = 30502,
        text = "识别名为“炎魔”，能够通过变换黑白两色的发带来改变性格，日常是腹黑的司令官形态。",
        minipack = 0,
    },
    [2200130] = {
        id = 2200130,
        text = "召唤最终之剑，连续斩出4道巨大的剑气攻击前方敌人。\n对敌人造成4次共计攻击力750%的物理伤害。",
        minipack = 0,
    },
    [244011] = {
        id = 244011,
        text = "「青涩女仆」在擦洗盘子的时，不小心打碎了一叠盘子，营业额-100",
        minipack = 0,
    },
    [2200140] = {
        id = 2200140,
        text = "向指定方向快速冲刺一段距离。",
        minipack = 0,
    },
    [244012] = {
        id = 244012,
        text = "「青涩女仆」勤奋好学，调制的卡布奇诺深受客人喜爱",
        minipack = 0,
    },
    [63052] = {
        id = 63052,
        text = "        通过玩家问题电子屏、鄙视十香AI回答、训练实验室活动可对十香进行训练。\n        问题电子屏：记录着所有被鄙视的十香AI回答以及玩家提出的问题内容。玩家通过前往模仿训练再次对十香AI进行训练，审核成功后，删除问题电子屏原问题，十香AI回答将”随机”替换为审核成功的训练回答。\n        鄙视十香AI回答：专属聊天室中与十香AI的聊天中对十香AI的回答点击鄙视前往训练十香AI，可回答原问题也可自行修改问题进行训练。\n        训练实验室：输入想要训练十香AI的问题，模仿十香面对该问题可能作出的回答并记录，设置该训练触发的情景并提交。\n        审核列表：记录训练内容的状态。",
        minipack = 0,
    },
    [2200160] = {
        id = 2200160,
        text = "十香登场时，王座跟随降临，并攻击王座周围的敌人。\n对敌人造成1次攻击力300%的物理伤害。",
        minipack = 0,
    },
    [244013] = {
        id = 244013,
        text = "「青涩女仆」为客人们演唱了《裙子可以更短一点》，受到喜爱",
        minipack = 0,
    },
    [2200180] = {
        id = 2200180,
        text = "蓄力后，使用鏖杀公向前横扫出3道剑气攻击敌人。\n对敌人造成3次共计攻击力550%的物理伤害。",
        minipack = 0,
    },
    [190016145] = {
        id = 190016145,
        text = "夏拉姆·关卡",
        minipack = 0,
    },
