    },
    [1701583] = {
        id = 1701583,
        text = "嘿嘿，没想到会这么开心呢。",
        minipack = 0,
    },
    [1701584] = {
        id = 1701584,
        text = "啊啦，被你发现了呢，嘻嘻。",
        minipack = 0,
    },
    [1701585] = {
        id = 1701585,
        text = "不管来多少次，都觉得这里很不错呢。",
        minipack = 0,
    },
    [1701586] = {
        id = 1701586,
        text = "不要着急，慢慢来。",
        minipack = 0,
    },
    [1701587] = {
        id = 1701587,
        text = "那就待会儿见，我会很期待的。",
        minipack = 0,
    },
    [1701588] = {
        id = 1701588,
        text = "没关系，下次再加油。",
        minipack = 0,
    },
    [1701589] = {
        id = 1701589,
        text = "服装店？有很多有趣的回忆呢，嘻嘻。",
        minipack = 0,
    },
    [1701590] = {
        id = 1701590,
        text = "合适吗？……嘿嘿，你喜欢就好",
        minipack = 0,
    },
    [1701591] = {
        id = 1701591,
        text = "这件衣服，真漂亮呢。更喜欢我了吗？",
        minipack = 0,
    },
    [1701592] = {
        id = 1701592,
        text = "嗯？悄悄地跑来找我吗？嘻嘻~",
        minipack = 0,
    },
    [1701593] = {
        id = 1701593,
        text = "呐，是要送我礼物吗？",
        minipack = 0,
    },
    [1701594] = {
        id = 1701594,
        text = "这个……从来没有尝试过的味道",
        minipack = 0,
    },
    [1701595] = {
        id = 1701595,
        text = "谢谢你，的确很美味",
        minipack = 0,
    },
    [1701596] = {
        id = 1701596,
        text = "好开心，原来你一直都知道，我所喜欢的",
        minipack = 0,
    },
    [1701597] = {
        id = 1701597,
        text = "真的么？真的是给我的么？",
        minipack = 0,
    },
    [1701598] = {
        id = 1701598,
        text = "我一如既往，深深地爱着你。……开玩笑了",
        minipack = 0,
    },
    [1701599] = {
        id = 1701599,
        text = "想我了吗？没关系，我在这里哦。",
        minipack = 0,
    },
    [1701600] = {
        id = 1701600,
        text = "能感受到，大家的力量呢。",
        minipack = 0,
    },
    [1701601] = {
        id = 1701601,
        text = "？有什么事吗？",
        minipack = 0,
    },
    [1701602] = {
        id = 1701602,
        text = "我是裁定者。我要——看清你。",
        minipack = 0,
    },
    [1701603] = {
        id = 1701603,
        text = "这样……就能保护你了",
        minipack = 0,
    },
    [1701604] = {
        id = 1701604,
        text = "和大家相比，我还差得很远吧。",
        minipack = 0,
    },
    [1701605] = {
