    [1701991] = {
        id = 1701991,
        text = "哈，约会……？和我？你认真的？",
        minipack = 0,
    },
    [1701992] = {
        id = 1701992,
        text = "今天要做什么呀？",
        minipack = 0,
    },
    [1701993] = {
        id = 1701993,
        text = "你不挺厉害的嘛……",
        minipack = 0,
    },
    [1701994] = {
        id = 1701994,
        text = "约会……好像很开心的样子……不没什么。",
        minipack = 0,
    },
    [1701995] = {
        id = 1701995,
        text = "什么嘛……",
        minipack = 0,
    },
    [1701996] = {
        id = 1701996,
        text = "要拒绝的话就趁现在哦，真的可以吗？",
        minipack = 0,
    },
    [1701997] = {
        id = 1701997,
        text = "啊好好，我想也是。一点都没失落哦，这不是理所当然的么。",
        minipack = 0,
    },
    [1701998] = {
        id = 1701998,
        text = "我说，也没什么好看的吧。",
        minipack = 0,
    },
    [1701999] = {
        id = 1701999,
        text = "所以说别给我送衣服啦……",
        minipack = 0,
    },
    [1702000] = {
        id = 1702000,
        text = "谢谢你……我穿……好看吗？",
        minipack = 0,
    },
    [1702001] = {
        id = 1702001,
        text = "什么啊那是。哈？礼物？给我的？",
        minipack = 0,
