    [1702053] = {
        id = 1702053,
        text = "[主线]七罪_chapter 1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "拥有墨色如同黑夜般长发的少女，明亮的双眸是夜空最闪亮的星星。",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "即使拥有着强大战士的身份，也无法遮盖她萌动的少女心。",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "内心如玻璃般脆弱，害怕陌生人的她，总是需要你的呵护。",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "强大而残酷的力量，以及更加致命的美貌。",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "她试图让自己永远保持冷静，却总是迷失在哥哥的温情中。",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "「爱」是她存在的唯一理由，就像天使般高高在上。",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "只有在值得信赖的人面前，才会露出本来面目。",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "情人节吗？唔姆……对我来说只要能和你约会，那就是个好日子。\n和我在一起你也很快乐，对吗？",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "亲爱的恋人，希望你今天能接受我的鲜花和情书。\n来吧，和我一起共度良宵！",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "四糸乃已经比以前坚强了许多……\n情……情人……节快乐~",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "啊啦，虽然是命中注定的相遇，但我偶尔也会觉得幸运呢～\n能在时间的长河里等到你。",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "笨蛋哥哥，虽然这是属于情人们的节日，但我也有话想对你说。\n一直以来，感谢有你相伴。",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "今天我要更多地牵你的手，走在鲜花盛开的原野，或者落英缤纷的树下。\n直到夕阳余晖将我们的影子拉长。",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "其实我偶尔也想对你敞开心扉……\n只是在等待最美好的时刻。",
        minipack = 0,
    },
