    [1702415] = {
        id = 1702415,
        text = "",
        minipack = 0,
    },
    [1702416] = {
        id = 1702416,
        text = "建造精灵公寓的时候，琴里打算让每个精灵都居住在粉色的世界里，就算是高傲如狂三，偶尔也会有少女的一面吧？（虽然狂三不住在这里^0^）",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "想要捕捉精灵们的日常生活，就到精灵公寓的客厅多转转吧，不拘小节的精灵们，也许会给你一些特殊福利哦~",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "夜晚的精灵公寓房间，是精灵们安睡的地方，这里可以俯瞰大半个天宫市的夜景，但愿能带给她们一个浪漫的梦境。",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "夜晚的精灵公寓客厅，如果电视机发出柔和的冷光，你一定会听到四糸奈的吵嚷、七罪的尖叫，因为晚间剧正在播放。",
        minipack = 0,
    },
    [1702420] = {
        id = 1702420,
        text = "虽然曾经被邀请参加茶会时，只留下了胆战心惊的回忆……不，就算现在也很胆战心惊啊。",
        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "即使明媚的阳光，也不能照亮精灵们压抑的心情，我堂堂精灵大人，为什么要乖乖坐在这里听讲啊？真是让人头大。",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "空空荡荡的屋顶，偶尔也会吸引偷懒的学生过来聚会，据说有人曾经在屋顶上见到过神秘的红衣少女，那美丽的脸庞让人难忘。",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "会让某些人想起罚站经历的教室走廊，一到下课时间这里就会变得非常热闹，美好的时光也从这里悄悄消逝……",
        minipack = 0,
    },
    [221001] = {
        id = 221001,
        text = "约会数据不存在",
        minipack = 0,
    },
    [1702426] = {
        id = 1702426,
        text = "据说这里是最佳观赏月亮的地方，不过晚上很少会有人了来天台吧？如果偶然看到一个孤独的少女背影，也请不要太惊讶。",
        minipack = 0,
    },
    [1702427] = {
        id = 1702427,
        text = "夜晚的学校走廊是个安静的去处，不过看起来不大适合约会的样子，也许只有特别的精灵，才会想要到这种僻静的地方来吧？",
