    [2101114] = {
        id = 2101114,
        text = "一股书香阴面扑来，柜子里整整齐齐的放着约会大作战官方小说集。",
        minipack = 0,
    },
    [2101116] = {
        id = 2101116,
        text = "放着两张未使用的电影票，日期是【2020.9.21】……（等等！这一天不就是游戏公测的日期吗？）",
        minipack = 0,
    },
    [2101118] = {
        id = 2101118,
        text = "柜子里面装满了约会大作战的各种周边，柜子正中规规整整的写着“希望我们的约战能越做越好！”",
        minipack = 0,
    },
    [2101120] = {
        id = 2101120,
        text = "“我的老婆是琴里！我的女儿是小四！”柜子里面写满了这样的口号。",
        minipack = 0,
    },
    [2101122] = {
        id = 2101122,
        text = "里面塞满了加班买肥宅套餐所赠送的炸鸡优惠券，不过好像都过期了。",
        minipack = 0,
    },
    [2101124] = {
        id = 2101124,
        text = "柜子里面贴满了海报，中间有两张张折纸的海报分别写着【Angel】和【Devil】。",
        minipack = 0,
    },
    [2101126] = {
        id = 2101126,
        text = "有一条超大横幅，上面写着：冤有头债有主，你们老婆不是我画崩的。",
        minipack = 0,
    },
    [2101128] = {
        id = 2101128,
        text = "里面竟然是一大堆官方定制的约战周边，有手办、挂画和立牌。（要不要拿走？）",
        minipack = 0,
    },
    [2101130] = {
        id = 2101130,
        text = "有一张照片，好像是某站知名舞见的签名照？",
        minipack = 0,
    },
    [2101132] = {
        id = 2101132,
        text = "有一张便签纸，上面用红笔写着【蒋boss的头发】，（这是什么暗号吗？）",
        minipack = 0,
    },
    [2101134] = {
        id = 2101134,
