        minipack = 0,
    },
    [10961162] = {
        id = 10961162,
        text = "[双段突刺]最后挥击产生风暴。技能总共可造成角色攻击力940%的暴风伤害。",
        minipack = 0,
    },
    [10961170] = {
        id = 10961170,
        text = "[风尘龙卷]将敌人卷入空中后，发动额外的追击。总共可以造成角色攻击力890%的暴风伤害。",
        minipack = 0,
    },
    [10961178] = {
        id = 10961178,
        text = "[风尘龙卷]结束追击后，重击地面，发动冲击波击飞敌人。总共可以造成角色攻击力1090%的暴风伤害。",
        minipack = 0,
    },
    [10961186] = {
        id = 10961186,
        text = "[风尘龙卷]重击地面后，会形成风暴持续造成伤害。总共可以造成角色攻击力1330%的暴风伤害。",
        minipack = 0,
    },
    [10961194] = {
        id = 10961194,
        text = "[翡翠牢笼]展开真空立场后不再持续造成伤害，而是在受到友方攻击时发生爆炸，每次爆炸最低间隔0.5s。真空立场会在爆炸5次后，或存在5秒后消失。该技能总共可以造成角色攻击力1300%的暴风伤害。",
        minipack = 0,
    },
