    [2201523] = {
        id = 2201523,
        text = "[萌物动员]：把七罪的敌人都变成可爱的小动物！技能总共可造成攻击力300%的魔力伤害。boss免疫变形。\n兔子：移动速度减少30%，防御力减少10%\n仓鼠：移动速度减少30%，抗暴率减少10%\n熊猫：移动速度减少30%，闪避率减少10%\n[厄运眷属]：召唤8只魔女的眷属，快速飞向目标发出自杀性攻击爆炸。技能总共可造成攻击力400%的魔力伤害。",
        minipack = 0,
    },
    [2201525] = {
        id = 2201525,
        text = "[鏖杀公(伪)]：把赝造魔女变化为鏖杀公，发出巨大的剑气毁灭前方敌人。技能总可共造成攻击力800%的物理伤害。\n[赝造魔女]：赝造魔女最强大的能力，把敌人全部变为可爱的小动物后，再他们吸入到赝造魔女之中。然后形成能量风暴产生巨大的伤害。技能总共可造成攻击力1600%的魔力伤害。",
        minipack = 0,
    },
