    [15011510] = {
        id = 15011510,
        text = "更新日期：2021年8月12日\n生效日期：2021年8月12日\n欢迎您选择由黑桃公司（以下简称“我们”。本指引中的黑桃公司，具体是指黑桃游戏及其服务的提供方上海黑桃互动网络科技股份有限公司，注册地为上海市嘉定区沪宜公路5358号3层J589室）提供的黑桃游戏及服务！除、外，我们还将通过（“本政策”） 帮助您和您的孩子（本政策中的“孩子”，是指不满十四周岁的未成年人）进一步了解我们收集、使用、存储和共享您孩子个人信息的情况，以及您和您的孩子所享有的相关权利。\n",
        minipack = 0,
    },
    [15011518] = {
        id = 15011518,
        text = "一般我们不会向第三方转移和委托第三方处理儿童个人信息，如确需第三方转移或委托第三方处理的，我们都会根据法律、行政法规的规定进行合规措施，包括但不限于对第三方进行安全评估、签署委托协议。\n",
        minipack = 0,
    },
    [15011526] = {
        id = 15011526,
        text = "\n\n3.可领取奖励在活动结束后不会自动补发，还请及时领取，以免造成损失",
        minipack = 0,
    },
    [15011534] = {
        id = 15011534,
        text = "通过活动获得的高级材料，可在“花灯”建筑中升级花灯，在“望月言欢”活动中获得。",
        minipack = 0,
