    [15011542] = {
        id = 15011542,
        text = "不知秋思落谁家",
        minipack = 0,
    },
    [15011550] = {
        id = 15011550,
        text = "夕弦那家伙，肯定是搞错了。满月和大刀，这是何等雄伟的气魄，怎么是在抒发思乡之情呢？诗人一定是个万夫莫敌的将军吧。——耶俱矢对自己的论断充满了信心。",
        minipack = 0,
    },
    [15011558] = {
