    [13310528] = {
        id = 13310528,
        text = "亲爱的誓约者：\n        感谢大家对约战和大凉山的支持，在大家的陪伴下，精灵们也即将迎来第一个春节，第一个有大家陪伴的春节。\n        约战因为有大家的支持！才能够不断变好，变强，大凉山制作组也会不懈努力，砥砺前行！\n                约战不倒，陪你到老！\n                                                                大凉山制作组",
        minipack = 0,
    },
    [13310536] = {
        id = 13310536,
        text = "",
        minipack = 0,
    },
    [13310544] = {
        id = 13310544,
        text = "亲爱的誓约者：\n        约战-精灵再临 在您的支持下已经度过一岁生日了。感谢长期以来陪伴。 \n        这1年，热恋如歌，约战有你，雨化浓情，露含蜜意。\n        这1年，激战正酣，约战有你，挑战无垠，进击无限。\n        这1年，我们用心筑建爱的大楼，携手眺望浪漫的城市。\n        展望未来，我们誓守陪伴之约，将与你创造更多甜蜜回忆。\n        值此1周年之际，我们重新启辰，承诺为你延续温暖，带来更多惊喜。\n        约战不倒，陪你到老~ ",
        minipack = 0,
    },
