    [23006] = {
        id = 23006,
        text = "三三限定手办，未来的每一天约战都为你应援。排行结束后，在活动界面填写收件地址。实物奖励将在活动结束后，通过快递邮寄给您！",
        minipack = 0,
    },
    [14210218] = {
        id = 14210218,
        text = "修学旅行的途中！双胞胎姐妹八舞耶俱矢和八舞夕弦，争夺实力之名的决斗正在上演！——“放马过来吧！”",
        minipack = 0,
    },
    [14210217] = {
        id = 14210217,
        text = "认定五河琴里是杀害自己父母的凶手，无法控制复仇烈焰的折纸！——“去死吧，精灵！”",
        minipack = 0,
    },
    [14210216] = {
        id = 14210216,
        text = "突然出现扭转局势的五河琴里，失控进入了暴走的状态。——“梦魇，你可别让我失望啊！”",
        minipack = 0,
    },
    [27102] = {
        id = 27102,
        text = "雷雨山庄线索信物。平平无奇的侦探帽，没有什么特殊作用，只是会一直陪伴你找到最终的答案！",
        minipack = 0,
    },
    [225002] = {
        id = 225002,
        text = "此位置已有装备",
        minipack = 0,
    },
    [14210215] = {
        id = 14210215,
        text = "哼，终于被我找到了！名为梦魇的精灵，这一次，就让你看看我崇宫真那的厉害！",
        minipack = 0,
    },
    [14210214] = {
        id = 14210214,
        text = "突发！被AST包围四糸乃，我不能让任何人靠近她的结界！——“回应我的召唤吧！sandalphon！”",
        minipack = 0,
    },
    [14210213] = {
        id = 14210213,
        text = "新精灵发现！识别名为“Hermit”的精灵四糸乃。诱捕计划正在展开！",
        minipack = 0,
    },
    [450001] = {
        id = 450001,
        text = "觉",
        minipack = 0,
    },
    [14210212] = {
        id = 14210212,
        text = "出现就引发灾难的神秘少女——“精灵”，率领AST赶赴现场的鸢一折纸。激战一触即发！",
        minipack = 0,
    },
    [14210211] = {
        id = 14210211,
        text = "        时间的魔力不在于将水滴穿石、磨石成沙，而在于一年后的你，依旧记得那一天的感动，亲爱的，一周年快乐！",
        minipack = 0,
