    [1140077] = {
        id = 1140077,
        text = "合成八舞耶俱矢SS级普攻宝石所必须的材料",
        minipack = 0,
    },
    [63006] = {
        id = 63006,
        text = "        质点改造可以将目标质点随机属性的数值提升到所在品质的极限。\n        进行改造时，所增长的随机属性值会在一定范围内随机。质点回收时，之前所消耗的改造材料也会一并返还。",
        minipack = 0,
    },
    [3202058] = {
        id = 3202058,
        text = "结算积分/作战评分",
        minipack = 0,
    },
    [3004024] = {
        id = 3004024,
        text = "据点信息",
        minipack = 0,
    },
    [63005] = {
        id = 63005,
        text = "        回收功能可以让已经强化、改造之后的质点重置为初始状态，并返还之前消耗的材料（洗练质点消耗的材料不会返还）。\n        质点回收分为免费回收和完全回收2种方式。免费回收不消耗任何道具，但只会返还30%的强化材料；完全回收会返还全部强化材料，但需要根据质点的当前等级消耗一定的钻石。\n        此外，在进行质点洗练、出售等消耗质点的操作时，均会自动执行免费回收。",
        minipack = 0,
    },
    [12909] = {
        id = 12909,
        text = "防御力-10%，受伤减免-10%，每2秒恢复1点sp",
        minipack = 0,
    },
    [3004019] = {
